    @if($materialIssue?->status === 'POSTED' && auth()->user()->hasPermission('production.execution.prepare'))<div class="modal fade" id="material-return-modal" tabindex="-1" aria-labelledby="material-return-title" aria-hidden="true"><div class="modal-dialog"><form class="modal-content" id="material-return-form" data-url="{{ route('production.orders.material-return', $order) }}"><div class="modal-header"><h2 class="modal-title fs-5" id="material-return-title">สร้างใบรับคืนวัตถุดิบ</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="ปิด"></button></div><div class="modal-body"><p class="text-secondary small">ระบบจะสร้างจากจำนวนวัตถุดิบที่ยังรับคืนได้ทั้งหมด</p><label class="form-label" for="material-return-reason">เหตุผล <span class="text-danger">*</span></label><textarea class="form-control" id="material-return-reason" name="reason" required minlength="10" maxlength="500">คืนวัตถุดิบจาก WO {{ $order->document_number }}</textarea><div class="invalid-feedback"></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">ปิด</button><button class="btn btn-app-primary" type="submit"><i class="bx bx-undo me-1" aria-hidden="true"></i>สร้างใบรับคืนวัตถุดิบ</button></div></form></div></div>@endif
